CREATE OR REPLACE FUNCTION clinlims.freeze_qc_violation_evidence()
RETURNS trigger AS $body$
BEGIN
  IF NEW.triggering_result_id IS DISTINCT FROM OLD.triggering_result_id
     OR NEW.rule_code IS DISTINCT FROM OLD.rule_code
     OR NEW.violation_date_time IS DISTINCT FROM OLD.violation_date_time
     OR NEW.severity IS DISTINCT FROM OLD.severity
     OR NEW.instrument_id IS DISTINCT FROM OLD.instrument_id
     OR NEW.test_id IS DISTINCT FROM OLD.test_id THEN
    RAISE EXCEPTION 'QC violation release evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$body$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_freeze_qc_violation_evidence ON clinlims.qc_rule_violation;
CREATE TRIGGER trg_freeze_qc_violation_evidence
BEFORE UPDATE ON clinlims.qc_rule_violation
FOR EACH ROW EXECUTE FUNCTION clinlims.freeze_qc_violation_evidence();
